package net.officefloor.hq.app.period;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.pool.FrozenCuts;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Soft-closes an open period: its due-total and each person's figure are fixed as a close fixes them,
 * but claims dated inside it can still be added, edited, opened, settled and voided. The same roles
 * as may close may soft-close; a period already closed or soft-closed is refused.
 */
public class SoftClosePeriod {
    public void close(@Val Sheet sheet, @Val Period period, PeriodRepository periods, PersonRepository people,
            ClaimRepository claims, ClaimLogRepository log, RateRepository rates, SettingsRepository settings, RoleRepository roles,
            FrozenCuts frozen, HttpServletRequest request, Out<Period> closedOut) throws InvalidPeriodException {
        String role = roles.roleOf(sheet.id(), Audit.user(request));
        if (!settings.find(sheet.id()).allows("close", role)) {
            throw new InvalidPeriodException("A " + role + " may not soft-close period " + period.name());
        }
        if (period.closed()) throw new InvalidPeriodException("Period " + period.name() + " is already closed");
        Period closed = ClosePeriod.fix(sheet, period, true, periods, people, claims, log, rates, settings, frozen);
        if (closed == null) throw new InvalidPeriodException("Period " + period.name() + " is already closed");
        closedOut.set(closed);
    }
}
package net.officefloor.hq.app.period;

import jakarta.servlet.http.HttpServletRequest;
import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigure;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.pool.FrozenCuts;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Closes the period, fixing its due-total at this moment: the figures of the claims that counted at
 * the end of its last day, by the status their log records then (OPEN, PENDING and SETTLED, but not an
 * unbound open one of a person whose retirement date is reached, nor one deferred now), due by a date inside it (an overdue one with its late charge), added up, skipping n/a. Each person's own figure for the period is fixed
 * too, and the period's due-total is the sum of them; and so is each person's carried figure for it. A soft-closed period closes too, its figures
 * fixed afresh. Every pool member's cut is fixed for it too, as it stands at this moment. A period already closed is refused, and so is a role the permission matrix does not allow to close.
 */
public class ClosePeriod {
    public void close(@Val Sheet sheet, @Val Period period, PeriodRepository periods, PersonRepository people,
            ClaimRepository claims, ClaimLogRepository log, RateRepository rates, SettingsRepository settings, RoleRepository roles,
            FrozenCuts frozen, HttpServletRequest request, Out<Period> closedOut) throws InvalidPeriodException {
        String role = roles.roleOf(sheet.id(), Audit.user(request));
        if (!settings.find(sheet.id()).allows("close", role)) {
            throw new InvalidPeriodException("A " + role + " may not close period " + period.name());
        }
        if (period.hardClosed()) throw new InvalidPeriodException("Period " + period.name() + " is already closed");
        Period closed = fix(sheet, period, false, periods, people, claims, log, rates, settings, frozen);
        if (closed == null) throw new InvalidPeriodException("Period " + period.name() + " is already closed");
        closedOut.set(closed);
    }

    /**
     * Fixes the open (or soft-closed) period's due-total, and each person's, as at the sheet's today,
     * and marks it closed, or soft-closed when {@code soft}, in the store: the closed period, or null
     * when another request changed it first.
     */
    static Period fix(Sheet sheet, Period period, boolean soft, PeriodRepository periods, PersonRepository people,
            ClaimRepository claims, ClaimLogRepository log, RateRepository rates, SettingsRepository settings, FrozenCuts frozen) {
        List<Rate> all = rates.findAll(sheet.id());
        Settings sheetSettings = settings.find(sheet.id());
        List<Claim> sheetClaims = claims.findAll(sheet.id());
        Map<Long, ClaimStatus> statusesThen = log.statusesOn(sheet.id(), period.to());
        List<Period> sheetPeriods = periods.findAll(sheet.id());
        Map<Long, BigDecimal> openings = periods.personOpenings(period);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        Map<Long, BigDecimal> personCarried = new LinkedHashMap<>();
        for (Person person : people.findAll(sheet.id())) {
            BigDecimal personTotal = BigDecimal.ZERO.setScale(2);
            for (Claim claim : sheetClaims) {
                if (claim.getPersonId() != person.getId() || !period.contains(claim.getDueBy())) continue;
                if (!claim.countsAsOf(statusesThen.get(claim.getId()), person.heldOn(claim.getDate(), sheet.today()), sheet.today())) continue;
                BigDecimal figure = ClaimFigure.withLate(claim, all, person.gradeOn(claim.getDate()), sheetSettings, sheet.today());
                if (figure != null) personTotal = personTotal.add(figure);
            }
            personTotals.put(person.getId(), personTotal);
            personCarried.put(person.getId(), carried(sheet, period, sheetPeriods, person, sheetClaims, statusesThen, all, sheetSettings)
                    .add(openings.getOrDefault(person.getId(), BigDecimal.ZERO)).setScale(2));
            total = total.add(personTotal);
        }
        Period closed = soft ? period.softClose(total) : period.close(total);
        if (!periods.markClosed(closed, period.soft())) return null;
        periods.deletePersonTotals(closed);
        periods.savePersonTotals(closed, personTotals);
        periods.deletePersonCarried(closed);
        periods.savePersonCarried(closed, personCarried);
        frozen.freeze(sheet, closed);
        return closed;
    }

    /**
     * The person's carried figure for the period, as the screen works it while the period is open:
     * the figures of their claims that count and belong to a period (by due-by) ending before this one
     * starts, and were still OPEN or PENDING at the end of this period's last day by the status their
     * log records then, added up, skipping n/a. (Its opening balance is added by the caller.)
     */
    private static BigDecimal carried(Sheet sheet, Period period, List<Period> sheetPeriods, Person person,
            List<Claim> sheetClaims, Map<Long, ClaimStatus> statusesThen, List<Rate> all, Settings sheetSettings) {
        BigDecimal carried = BigDecimal.ZERO.setScale(2);
        for (Claim claim : sheetClaims) {
            if (claim.getPersonId() != person.getId() || claim.getDueBy() == null) continue;
            Period own = sheetPeriods.stream().filter((p) -> p.contains(claim.getDueBy())).findFirst().orElse(null);
            if (own == null || !own.to().isBefore(period.from())) continue;
            ClaimStatus then = statusesThen.get(claim.getId());
            if (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING) continue;
            if (!claim.countsAsOf(then, person.heldOn(claim.getDate(), sheet.today()), sheet.today())) continue;
            BigDecimal figure = ClaimFigure.withLate(claim, all, person.gradeOn(claim.getDate()), sheetSettings, sheet.today());
            if (figure != null) carried = carried.add(figure);
        }
        return carried;
    }
}
package net.officefloor.hq.app.period;

import jakarta.servlet.http.HttpServletRequest;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.role.StewardOnlyException;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Undoes the sheet's last rollover: the periods it generated are removed and the opening balances it
 * added are taken back; ROLLOVER_UNDONE with its old year. Only the steward who made it may, on the
 * same sheet-today it was made. Refused when there is no rollover, it is already undone, or a claim
 * (in any status, voided too) belongs to a period it generated, by its date or its due-by.
 */
public class UndoRollover {
    public void undo(@Val Sheet sheet, PeriodRepository periods, RolloverRepository rollovers, ClaimRepository claims,
            RoleRepository roles, HttpServletRequest request, Audit audit, Out<GeneratePeriodsResponse> result)
            throws StewardOnlyException, InvalidPeriodException {
        String user = Audit.user(request);
        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), user))) {
            throw new StewardOnlyException("Only a steward may undo a rollover");
        }
        Rollover last = rollovers.last(sheet.id());
        if (last == null || last.undone()) throw new InvalidPeriodException("There is no rollover to undo");
        if (!last.madeBy().equals(user)) {
            throw new InvalidPeriodException("Only " + last.madeBy() + " may undo their rollover");
        }
        if (!last.madeOn().equals(sheet.today())) {
            throw new InvalidPeriodException("A rollover is undone only on the day it was made");
        }
        List<Period> generated = periods.findAll(sheet.id()).stream()
                .filter((p) -> last.periods().contains(p.name())).toList();
        for (Claim claim : claims.findAll(sheet.id())) {
            for (Period p : generated) {
                if ((claim.getDate() != null && p.contains(claim.getDate()))
                        || (claim.getDueBy() != null && p.contains(claim.getDueBy()))) {
                    throw new InvalidPeriodException("A claim belongs to period " + p.name());
                }
            }
        }
        if (!rollovers.markUndone(last)) throw new InvalidPeriodException("The rollover is already undone");
        for (Rollover.Opening o : last.openings()) {
            periods.subtractOpening(sheet.id(), o.periodName(), o.personId(), o.amount());
        }
        for (Period p : generated) periods.delete(sheet.id(), p.name());
        audit.record("ROLLOVER_UNDONE sheet=" + sheet.id() + " by=" + user + " fy=" + last.fy());
        result.set(new GeneratePeriodsResponse(generated.size()));
    }
}
package net.officefloor.hq.app.period;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.pool.FrozenCuts;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Once the sheet's today is changed: closes every open period whose to-date plus the sheet's grace
 * days is before the new today, in order of their to-dates, exactly as a close by hand would, each
 * recording PERIOD_CLOSED with auto=yes as it closes. Nothing closes while the grace days are off.
 */
public class AutoClosePeriods {
    public void close(@Val Sheet sheet, @Val LocalDate today, PeriodRepository periods, PersonRepository people,
            ClaimRepository claims, ClaimLogRepository log, RateRepository rates, SettingsRepository settings,
            FrozenCuts frozen, HttpServletRequest request, Audit audit) {
        Settings sheetSettings = settings.find(sheet.id());
        Sheet now = new Sheet(sheet.id(), today, sheet.archived());
        List<Period> due = periods.findAll(sheet.id()).stream()
                .filter((p) -> !p.closed() && sheetSettings.pastGrace(p.to(), today))
                .sorted(Comparator.comparing(Period::to)).toList();
        for (Period period : due) {
            Period closed = ClosePeriod.fix(now, period, false, periods, people, claims, log, rates, settings, frozen);
            if (closed == null) continue; // another request closed it first
            audit.record("PERIOD_CLOSED sheet=" + sheet.id() + " by=" + Audit.user(request)
                    + " period=" + closed.name() + " total=" + closed.closedTotal().setScale(2).toPlainString()
                    + " auto=yes");
        }
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A period on a sheet: its name (unique on the sheet), its from and to dates, inclusive, whether it
 * is closed, and the due-total fixed when it was closed (null while open). A soft-closed period is
 * closed with {@code soft} set: its figures are fixed, but claims dated inside it can still change.
 * Its cap, when set, is the most OPEN or PENDING claims a person may have due by a date in it.
 * A locked period cannot be reopened until a steward unlocks it.
 */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
        BigDecimal closedTotal, boolean soft, Integer cap, boolean locked) {

    public Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
            BigDecimal closedTotal, boolean soft, Integer cap) {
        this(sheetId, name, from, to, closed, closedTotal, soft, cap, false);
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this(sheetId, name, from, to, null);
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to, Integer cap) {
        this(sheetId, name, from, to, false, null, false, cap);
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
            BigDecimal closedTotal, boolean soft) {
        this(sheetId, name, from, to, closed, closedTotal, soft, null);
    }

    /** Whether the two periods share a day. */
    public boolean overlaps(Period other) {
        return !from.isAfter(other.to) && !other.from.isAfter(to);
    }

    /** Whether the date falls in the period. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }

    /** This period, closed with its due-total fixed. */
    public Period close(BigDecimal total) {
        return new Period(sheetId, name, from, to, true, total, false, cap, locked);
    }

    /** This period, soft-closed with its due-total fixed. */
    public Period softClose(BigDecimal total) {
        return new Period(sheetId, name, from, to, true, total, true, cap, locked);
    }

    /** Whether it is closed for good: claims dated inside it cannot change. */
    public boolean hardClosed() {
        return closed && !soft;
    }

    /** This period, reopened: its due-total live again. */
    public Period reopen() {
        return new Period(sheetId, name, from, to, false, null, false, cap, locked);
    }

    /** This period, locked or unlocked. */
    public Period withLocked(boolean locked) {
        return new Period(sheetId, name, from, to, closed, closedTotal, soft, cap, locked);
    }
}

